import{_ as p,a0 as o,w as r,s as d,I as a,x as e,a1 as n,A as i,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如何使用 Apache Web 服務器配置多個站點 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Apache Web 服務器配置多個站點 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Apache Web 服務器配置多個站點 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Apache Web 服務器配置多個站點 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180329 How to configure multiple websites with Apache web server","title":"如何使用 Apache Web 服務器配置多個站點","tag":"201810","desc":""},"relativePath":"201810/20180329 How to configure multiple websites with Apache web server.md","filePath":"[post].md"}'),h={name:"201810/20180329 How to configure multiple websites with Apache web server.md"};function c(g,s,b,u,k,m){const t=o("Link");return r(),d("div",null,[s[21]||(s[21]=a("h1",{id:"如何使用-apache-web-服務器配置多個站點",tabindex:"-1"},[e("如何使用 Apache Web 服務器配置多個站點 "),a("a",{class:"header-anchor",href:"#如何使用-apache-web-服務器配置多個站點","aria-label":"Permalink to “如何使用 Apache Web 服務器配置多個站點”"},"​")],-1)),s[22]||(s[22]=a("blockquote",null,[a("p",null,"如何在流行而強大的 Apache Web 服務器上託管兩個或多個站點。")],-1)),s[23]||(s[23]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/apache-feathers.jpg?itok=fnrpsu3G",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("在我的",-1)),n(t,{href:"https://linux.cn/article-9506-1.html"},{default:i(()=>[...s[0]||(s[0]=[e("上一篇文章",-1)])]),_:1}),s[2]||(s[2]=e("中，我解釋瞭如何為單個站點配置 Apache Web 服務器，事實證明這很容易。在這篇文章中，我將向你展示如何使用單個 Apache 實例來服務多個站點。",-1))]),s[24]||(s[24]=l('<p>注意：我寫這篇文章的環境是 Fedora 27 虛擬機，配置了 Apache 2.4.29。如果你用另一個發行版或不同的 Fedora 版本，那麼你使用的命令以及配置文件的位置和內容可能會有所不同。</p><p>正如我之前的文章中提到的，Apache 的所有配置文件都位於 <code>/etc/httpd/conf</code> 和 <code>/etc/httpd/conf.d</code>。默認情況下，站點的數據位於 <code>/var/www</code> 中。對於多個站點，你需要提供多個位置，每個位置對應託管的站點。</p><h3 id="基於名稱的虛擬主機" tabindex="-1">基於名稱的虛擬主機 <a class="header-anchor" href="#基於名稱的虛擬主機" aria-label="Permalink to “基於名稱的虛擬主機”">​</a></h3><p>使用基於名稱的虛擬主機，你可以為多個站點使用一個 IP 地址。現代 Web 服務器，包括 Apache，使用指定 URL 的 <code>hostname</code> 部分來確定哪個虛擬 Web 主機響應頁面請求。這僅僅需要比一個站點更多的配置。</p><p>即使你只從單個站點開始，我也建議你將其設置為虛擬主機，這樣可以在以後更輕鬆地添加更多站點。在本文中，我將從上一篇文章中我們停止的地方開始，因此你需要設置原來的站點，即基於名稱的虛擬站點。</p><h3 id="準備原來的站點" tabindex="-1">準備原來的站點 <a class="header-anchor" href="#準備原來的站點" aria-label="Permalink to “準備原來的站點”">​</a></h3>',6)),a("p",null,[s[4]||(s[4]=e("在設置第二個站點之前，你需要為現有網站提供基於名稱的虛擬主機。如果你現在沒有站點，",-1)),n(t,{href:"https://linux.cn/article-9506-1.html"},{default:i(()=>[...s[3]||(s[3]=[e("請返回並立即創建一個",-1)])]),_:1}),s[5]||(s[5]=e("。",-1))]),s[25]||(s[25]=l(`<p>一旦你有了站點，將以下內容添加到 <code>/etc/httpd/conf/httpd.conf</code> 配置文件的底部（添加此內容是你需要對 <code>httpd.conf</code> 文件進行的唯一更改）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;VirtualHost 127.0.0.1:80&gt;</span></span>
<span class="line"><span>    DocumentRoot /var/www/html</span></span>
<span class="line"><span>    ServerName www.site1.org</span></span>
<span class="line"><span>&lt;/VirtualHost&gt;</span></span></code></pre></div><p>這將是第一個虛擬主機配置節，它應該保持為第一個，以使其成為默認定義。這意味着通過 IP 地址或解析為此 IP 地址但沒有特定命名主機配置節的其它名稱對服務器的 HTTP 訪問將定向到此虛擬主機。所有其它虛擬主機配置節都應跟在此節之後。</p><p>你還需要使用 <code>/etc/hosts</code> 中的條目設置你的網站以提供名稱解析。上次，我們只使用了 <code>localhost</code> 的 IP 地址。通常，這可以使用你使用的任何名稱服務來完成，例如 Google 或 Godaddy。對於你的測試網站，通過在 <code>/etc/hosts</code> 中的 <code>localhost</code> 行添加一個新名稱來完成此操作。添加兩個網站的條目，方便你以後不需再次編輯此文件。結果如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>127.0.0.1 localhost localhost.localdomain localhost4 localhost4.localdomain4 www.site1.org www.site2.org</span></span></code></pre></div><p>讓我們將 <code>/var/www/html/index.html</code> 文件改變得更加明顯一點。它應該看起來像這樣（帶有一些額外的文本來識別這是站點 1）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;h1&gt;Hello World&lt;/h1&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Web site 1.</span></span></code></pre></div><p>重新啓動 HTTPD 服務器，已啓用對 <code>httpd</code> 配置的更改。然後，你可以從命令列使用 Lynx 文本模式查看網站。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@testvm1 ~]# systemctl restart httpd</span></span>
<span class="line"><span>[root@testvm1 ~]# lynx www.site1.org</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                                              Hello World </span></span>
<span class="line"><span>  Web site 1.</span></span>
<span class="line"><span>&lt;snip&gt;</span></span>
<span class="line"><span>Commands: Use arrow keys to move, &#39;?&#39; for help, &#39;q&#39; to quit, &#39;&lt;-&#39; to go back.</span></span>
<span class="line"><span>Arrow keys: Up and Down to move.  Right to follow a link; Left to go back.</span></span>
<span class="line"><span>H)elp O)ptions P)rint G)o M)ain screen Q)uit /=search [delete]=history list</span></span></code></pre></div><p>你可以看到原始網站的修改內容，沒有明顯的錯誤，先按下 <code>Q</code> 鍵，然後按 <code>Y</code> 退出 Lynx Web 瀏覽器。</p><h3 id="配置第二個站點" tabindex="-1">配置第二個站點 <a class="header-anchor" href="#配置第二個站點" aria-label="Permalink to “配置第二個站點”">​</a></h3><p>現在你已經準備好建立第二個網站。使用以下命令創建新的網站目錄結構：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@testvm1 html]# mkdir -p /var/www/html2</span></span></code></pre></div><p>注意，第二個站點只是第二個 <code>html</code> 目錄，與第一個站點位於同一 <code>/var/www</code> 目錄下。</p><p>現在創建一個新的索引文件 <code>/var/www/html2/index.html</code>，其中包含以下內容（此索引文件稍有不同，以區別於原來的網站）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;h1&gt;Hello World -- Again&lt;/h1&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Web site 2.</span></span></code></pre></div><p>在 <code>httpd.conf</code> 中為第二個站點創建一個新的配置節，並將其放在上一個虛擬主機配置節下面（這兩個應該看起來非常相似）。此節告訴 Web 服務器在哪裏可以找到第二個站點的 HTML 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;VirtualHost 127.0.0.1:80&gt;</span></span>
<span class="line"><span>    DocumentRoot /var/www/html2</span></span>
<span class="line"><span>    ServerName www.site2.org</span></span>
<span class="line"><span>&lt;/VirtualHost&gt;</span></span></code></pre></div><p>重啓 HTTPD，並使用 Lynx 來查看結果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@testvm1 httpd]# systemctl restart httpd</span></span>
<span class="line"><span>[root@testvm1 httpd]# lynx www.site2.org</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                                    Hello World -- Again</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   Web site 2.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;snip&gt;</span></span>
<span class="line"><span>Commands: Use arrow keys to move, &#39;?&#39; for help, &#39;q&#39; to quit, &#39;&lt;-&#39; to go back.</span></span>
<span class="line"><span>Arrow keys: Up and Down to move.  Right to follow a link; Left to go back.</span></span>
<span class="line"><span>H)elp O)ptions P)rint G)o M)ain screen Q)uit /=search [delete]=history list</span></span></code></pre></div><p>在這裏，我壓縮了輸出結果以適應這個空間。頁面的差異表明這是第二個站點。要同時顯示兩個站點，請打開另一個終端會話並使用 Lynx Web 瀏覽器查看另一個站點。</p><h3 id="其他考慮" tabindex="-1">其他考慮 <a class="header-anchor" href="#其他考慮" aria-label="Permalink to “其他考慮”">​</a></h3><p>這個簡單的例子展示瞭如何使用 Apache HTTPD 服務器的單個實例來服務於兩個站點。當考慮其他因素時，配置虛擬主機會變得有點複雜。</p><p>例如，你可能希望為這些網站中的一個或全部使用一些 CGI 腳本。為此，你可能為 CGI 程序在 <code>/var/www</code> 目錄下創建一些目錄：<code>/var/www/cgi-bin</code> 和 <code>/var/www/cgi-bin2</code>，以與 HTML 目錄命名一致。然後，你需要將配置指令添加到虛擬主機節，以指定 CGI 腳本的目錄位置。每個站點可以有下載文件的目錄。這還需要相應虛擬主機節中的條目。</p>`,24)),a("p",null,[n(t,{href:"https://httpd.apache.org/docs/2.4/"},{default:i(()=>[...s[6]||(s[6]=[e("Apache 網站",-1)])]),_:1}),s[7]||(s[7]=e("描述了管理多個站點的其他方法，以及從性能調優到安全性的配置選項。",-1))]),s[26]||(s[26]=a("p",null,"Apache 是一個強大的 Web 服務器，可以用來管理從簡單到高度複雜的網站。儘管其總體市場份額在縮小，但它仍然是互聯網上最常用的 HTTPD 服務器。",-1)),s[27]||(s[27]=a("hr",null,null,-1)),a("p",null,[s[9]||(s[9]=e("via: ",-1)),n(t,{href:"https://opensource.com/article/18/3/configuring-multiple-web-sites-apache"},{default:i(()=>[...s[8]||(s[8]=[e("https://opensource.com/article/18/3/configuring-multiple-web-sites-apache",-1)])]),_:1})]),a("p",null,[s[13]||(s[13]=e("作者：",-1)),n(t,{href:"https://opensource.com/users/dboth"},{default:i(()=>[...s[10]||(s[10]=[e("David Both",-1)])]),_:1}),s[14]||(s[14]=e(" 譯者：",-1)),n(t,{href:"https://github.com/MjSeven"},{default:i(()=>[...s[11]||(s[11]=[e("MjSeven",-1)])]),_:1}),s[15]||(s[15]=e(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:i(()=>[...s[12]||(s[12]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[16]||(s[16]=[e("LCTT",-1)])]),_:1}),s[19]||(s[19]=e(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:i(()=>[...s[17]||(s[17]=[e("Linux中國",-1)])]),_:1}),s[20]||(s[20]=e(" 榮譽推出",-1))])])}const y=p(h,[["render",c]]);export{v as __pageData,y as default};
